SELECT user_no
FROM USERS 
WHERE user_id = #{userId} 
  AND EMAIL = #{email, typeHandler=kr.co.sist.login.EncryptTypeHandler}

SELECT COUNT(*) 
FROM (
    SELECT verification_no 
    FROM VERIFICATIONCODE 
    WHERE user_no = #{userNo} 
    ORDER BY input_date DESC
) 
WHERE ROWNUM = 1 AND verification_no = #{verificationNo}
